    receive=acceleratedTravelTime(length,receiveSpeed,acceleration,deceleration);transfer=acceleratedTravelTime(length,transferSpeed,acceleration,deceleration);hold=acceleratedTravelTime(distance,travelSpeed,acceleration,deceleration);
